import {CATEGORIES,readingMinutes,selectStories,safeLoad,escapeHtml as esc,safeSourceUrl,editionEntry,readingState,safeImagePath} from './core.js?v=20261031-1';
const $=id=>document.getElementById(id);
let storage;try{storage=window.localStorage;}catch{storage=null;}
const legacy=safeLoad(storage,'xinliu:v1',{});
let stored=safeLoad(storage,'xinliu:v2',null);
if(!stored||typeof stored!=='object'||Array.isArray(stored))stored={...legacy,editions:{'2026-10-30':{readIds:legacy?.readIds,savedIds:legacy?.savedIds}}};
if(!stored.editions||typeof stored.editions!=='object'||Array.isArray(stored.editions))stored.editions={};
let state={category:'all',query:'',unread:false,savedOnly:false,readIds:[],savedIds:[],fontSize:Number.isInteger(stored.fontSize)&&stored.fontSize>=16&&stored.fontSize<=26?stored.fontSize:19,theme:stored.theme==='dark'?'dark':'light'};
let EDITION=null,catalog=null,activeStory=null,previousFocus=null,toastTimer,loading=false,requestId=0;
const editionCache=new Map();
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3400);}
function persist(){if(EDITION)stored.editions[EDITION.date]={readIds:state.readIds,savedIds:state.savedIds};Object.assign(stored,{fontSize:state.fontSize,theme:state.theme});try{storage.setItem('xinliu:v2',JSON.stringify(stored));}catch{toast('本次阅读记录暂存于页面中。');}}
function theme(){document.documentElement.dataset.theme=state.theme;$('theme').setAttribute('aria-label',state.theme==='dark'?'切换浅色模式':'切换深色模式');}
function applyFont(){document.documentElement.style.setProperty('--reader-size',state.fontSize+'px');$('font-down').disabled=state.fontSize<=16;$('font-up').disabled=state.fontSize>=26;}
function categoryName(id){return CATEGORIES.find(c=>c.id===id)?.name||id;}
function link(url,label){const href=safeSourceUrl(url);return href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);}
function photo(image,card=false){const path=safeImagePath(image?.src);if(!path)return '';return `<figure class="${card?'city-cover':'city-photo'}"><img src="${esc(path)}" alt="${esc(image.alt)}" loading="lazy" decoding="async" width="${Number(image.width)||1280}" height="${Number(image.height)||853}"><figcaption>${card?'':esc(image.caption)+' · '}${link(image.sourceUrl,image.author)} / ${link(image.licenseUrl,image.license)}${card?'':` · ${esc(image.takenAt||'')} · 缩放${image.cropped?'、展示裁切':''}`}</figcaption></figure>`;}
function card(s,i){const read=state.readIds.includes(s.id),saved=state.savedIds.includes(s.id),city=s.section==='city';return `<article class="story-card ${city?'city-card':i===0&&state.category==='all'&&!state.query&&!state.savedOnly?'featured':''}">${city?photo(s.images?.[0],true):''}<div class="${city?'city-card-copy':'card-copy'}"><div class="card-meta"><span class="section-label">${esc(categoryName(s.section))}</span><span>／</span><span>${esc(s.region)} · 约${readingMinutes([s])}分钟</span><span class="card-number">${city?'CITY':String(EDITION.stories.indexOf(s)+1).padStart(2,'0')}</span></div>${city?`<p class="city-kicker">${esc(s.city?.englishName)} · ${esc(s.city?.country)}</p>`:''}<h3 class="story-title"><button type="button" data-read="${esc(s.id)}">${esc(s.title)}</button></h3><p class="card-summary">${esc(s.summary)}</p><div class="card-footer"><span>${esc(city?'每日一城':s.freshness||'本期资讯')}</span>${read?'<span class="mini-dot"></span><span>✓ 已读</span>':''}<span class="card-arrow" aria-hidden="true">↗</span></div><button class="save-button ${saved?'saved':''}" type="button" data-save="${esc(s.id)}" aria-label="${saved?'取消收藏':'收藏'}：${esc(s.title)}" aria-pressed="${saved}">${saved?'▣':'▢'}</button></div></article>`;}
function render(){
  if(!EDITION)return;const selected=selectStories(EDITION.stories,state),city=EDITION.stories.find(s=>s.section==='city');
  $('categories').innerHTML=CATEGORIES.map(c=>`<button type="button" class="category ${c.id===state.category?'active':''}" data-category="${c.id}" aria-pressed="${c.id===state.category}"><span class="category-symbol" aria-hidden="true">${c.symbol}</span>${c.name}<span class="category-count">${c.id==='all'?EDITION.stories.length:EDITION.stories.filter(s=>s.section===c.id).length}</span></button>`).join('');
  $('cards').innerHTML=selected.map(card).join('');$('empty').hidden=selected.length>0;$('list-title').innerHTML=(state.savedOnly?'本期收藏':state.category==='all'?'本期精选':esc(categoryName(state.category)))+' <span>'+(state.category==='city'?'A CITY A DAY':'THE BRIEFING')+'</span>';
  $('result-count').textContent=state.category==='city'&&city?`${city.city?.country} · ${city.city?.englishName}`:`${selected.length} 篇内容${state.query?' · 搜索“'+state.query+'”':' · '+EDITION.date.replaceAll('-','.')}`;
  $('empty-title').textContent=state.savedOnly?'把值得再读的内容，留在这里。':state.category==='city'?'城市的篇章，从10月31日开始。':'暂时没有匹配的内容';$('empty-text').textContent=state.savedOnly?'点击文章右上角，即可收藏到这个浏览器。':state.category==='city'?'选择较新的日期，去看一座城市。':'换一个关键词，或试试其他栏目。';
  $('read-count').textContent=state.readIds.length;$('unread-count').textContent=EDITION.stories.length-state.readIds.length;$('saved-count').textContent=state.savedIds.length;$('progress-bar').style.width=100*state.readIds.length/EDITION.stories.length+'%';$('progress-ring').style.background=`conic-gradient(#647458 ${360*state.readIds.length/EDITION.stories.length}deg, ${state.theme==='dark'?'#4a5745':'#d6dacd'} 0deg)`;
  $('progress-note').textContent=state.readIds.length===EDITION.stories.length?'这一天，已经好好读过。':state.readIds.length?`已读${state.readIds.length}篇，还剩${EDITION.stories.length-state.readIds.length}篇。`:'从一篇开始，慢慢读。';
  $('edition-date').textContent=EDITION.date.replaceAll('-','.');$('minutes').textContent=readingMinutes(EDITION.stories);$('reader-total').textContent='/ '+EDITION.stories.length+' 篇';$('issue-number').textContent='NO. '+EDITION.issueNumber;$('notice-text').textContent=EDITION.intro||'从原始资料出发，把一天的消息读得清楚一些。';$('nav-edition').classList.toggle('active',!state.savedOnly);$('nav-saved').classList.toggle('active',state.savedOnly);$('date-picker').setAttribute('aria-label','选择日期，当前'+EDITION.date);
}
function citations(ids=[]){return ids.map(id=>`<a href="#source-${esc(id)}" data-citation="${esc(id)}" class="source-cite" aria-label="查看来源${esc(id)}">[${esc(id)}]</a>`).join(' ');}
function renderReader(){
  if(!activeStory)return;const s=activeStory,images=s.images||[];
  const prose=s.paragraphs.map((p,i)=>`${s.paragraphHeadings?.[i]?`<h3>${esc(s.paragraphHeadings[i])}</h3>`:''}<p>${esc(p)} ${citations(s.paragraphSources?.[i])}</p>${images[i+1]?photo(images[i+1]):''}`).join('');
  $('reader-content').innerHTML=`<div class="eyebrow"><span class="section-label">${esc(categoryName(s.section))}</span> · ${esc(s.region)} · 约${readingMinutes([s])}分钟</div><h2 id="reader-title">${esc(s.title)}</h2><p class="reader-meta">${esc(EDITION.date.replaceAll('-','.'))}${s.section==='city'?' · 城市手记':` · ${esc(s.freshness)} · 资料/事件 ${esc(s.eventDate)}`}</p><p class="reader-lead">${esc(s.summary)}</p>${images[0]?photo(images[0]):''}<div class="reader-prose">${prose}</div>${(s.perspectives||[]).map(p=>`<aside class="reader-angle"><h3>${esc(p.label)}</h3><p>${esc(p.text)} ${citations(p.sourceIds)}</p></aside>`).join('')}${s.uncertainty?`<p class="reader-context">${esc(s.uncertainty)}</p>`:''}<details class="reader-sources" id="reader-sources"><summary>资料与图片来源 <span>${s.sources.length} 项资料${images.length?' · '+images.length+' 张照片':''}</span></summary><p class="source-method">信流据公开资料原创整理 · AI辅助检索与写作 · 更新 ${esc(s.updatedAt.replace('T',' ').replace(/\+08:00$/,''))}</p>${s.sources.map(src=>`<div class="source-item" id="source-${esc(src.id)}"><strong>[${esc(src.id)}] ${esc(src.publisher)}</strong><p>${esc(src.title)}${src.publishedAt?'<br>发布 '+esc(src.publishedAt):''}${src.note?'<br>'+esc(src.note):''}</p>${link(src.url,'阅读原始资料 ↗')}</div>`).join('')}${images.length?'<p class="source-method">摄影作品依各自署名与许可使用；许可链接见每张图片下方。城市篇配图为注明年代的实景摄影。</p>':''}</details><div class="reader-actions"><button id="mark-read" type="button">${state.readIds.includes(s.id)?'✓ 已读 · 点击撤销':'读完了，标记已读'}</button><button id="reader-save" type="button">${state.savedIds.includes(s.id)?'▣ 已收藏':'▢ 收藏这篇'}</button></div>`;
  $('mark-read').onclick=()=>{state.readIds=state.readIds.includes(s.id)?state.readIds.filter(id=>id!==s.id):[...state.readIds,s.id];persist();render();renderReader();$('mark-read').focus();};$('reader-save').onclick=()=>{toggleSave(s.id);renderReader();$('reader-save').focus();};
}
function toggleSave(id){state.savedIds=state.savedIds.includes(id)?state.savedIds.filter(x=>x!==id):[...state.savedIds,id];persist();render();}
function openReader(id){activeStory=EDITION?.stories.find(s=>s.id===id);if(!activeStory)return;previousFocus=document.activeElement;renderReader();$('reader').showModal();$('reader').scrollTop=0;}
function closeReader(){$('reader').close();activeStory=null;if(previousFocus?.isConnected)previousFocus.focus();}
function resetFilters(){Object.assign(state,{category:'all',query:'',unread:false,savedOnly:false});$('unread').checked=false;$('search').value='';render();}
async function fetchJSON(url){const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw new Error('读取失败');return response.json();}
function chooseDateUI(){if(!catalog)return;$('date-input').min=catalog.editions.at(-1).date;$('date-input').max=catalog.latest;$('date-input').value=EDITION?.date||catalog.latest;$('date-error').textContent='';$('date-apply').disabled=false;$('available-dates').innerHTML=catalog.editions.map(e=>`<button type="button" class="date-option ${e.date===EDITION?.date?'selected':''}" data-edition-date="${esc(e.date)}" aria-pressed="${e.date===EDITION?.date}"><span><b>${esc(e.date.replaceAll('-','.'))}</b><small>NO. ${esc(e.issueNumber)}${e.city?' · '+esc(e.city):''}</small></span><span>${e.date===catalog.latest?'最新一期':'↗'}</span></button>`).join('');$('date-dialog').showModal();}
function validateDateInput(){const exists=!!editionEntry(catalog,$('date-input').value);$('date-error').textContent=exists?'':'这一天还没有简报，请从下方已出版日期选择。';$('date-apply').disabled=!exists;return exists;}
async function loadEdition(date,{historyMode='push'}={}){
  const entry=editionEntry(catalog,date);if(!entry){toast('这一天还没有简报。');return false;}const token=++requestId;loading=true;$('date-picker').disabled=true;$('cards').setAttribute('aria-busy','true');
  try{let edition=editionCache.get(date);if(!edition){edition=await fetchJSON(new URL(entry.path+'?v='+encodeURIComponent(entry.version),import.meta.url));if(edition.date!==date||!Array.isArray(edition.stories)||!edition.stories.length)throw new Error();editionCache.set(date,edition);}if(token!==requestId)return false;if(EDITION)persist();EDITION=edition;Object.assign(state,readingState(stored,date,edition.stories));resetFilters();if($('reader').open)closeReader();if($('date-dialog').open)$('date-dialog').close();if(historyMode){const url=new URL(location.href);url.searchParams.set('date',date);url.hash='';history[historyMode==='replace'?'replaceState':'pushState']({},'',url);}return true;
  }catch{if(token===requestId){$('date-error').textContent='这期暂未读到，请稍后重试。';toast('简报暂未读到，请重试。');if(!EDITION){$('load-error').hidden=false;$('result-count').textContent='暂时没有读到简报';}}return false;}finally{if(token===requestId){loading=false;$('date-picker').disabled=false;$('cards').setAttribute('aria-busy','false');}}
}
document.addEventListener('click',e=>{const cat=e.target.closest('[data-category]'),read=e.target.closest('[data-read]'),save=e.target.closest('[data-save]'),date=e.target.closest('[data-edition-date]'),cite=e.target.closest('[data-citation]');if(cat){state.category=cat.dataset.category;render();}else if(save){toggleSave(save.dataset.save);}else if(read){openReader(read.dataset.read);}else if(date){if(!loading)loadEdition(date.dataset.editionDate);}else if(cite){e.preventDefault();$('reader-sources').open=true;document.getElementById('source-'+cite.dataset.citation)?.scrollIntoView({block:'start'});}});
$('search').addEventListener('input',e=>{state.query=e.target.value;render();});$('unread').addEventListener('change',e=>{state.unread=e.target.checked;render();});$('nav-edition').onclick=resetFilters;$('nav-saved').onclick=()=>{resetFilters();state.savedOnly=true;render();};$('reset-filters').onclick=resetFilters;
for(const id of ['nav-about','notice-about','editor-about'])$(id).onclick=()=>$('about').showModal();$('about-close').onclick=()=>$('about').close();$('reader-close').onclick=closeReader;$('reader').addEventListener('cancel',()=>{activeStory=null;});
$('date-picker').onclick=chooseDateUI;$('date-close').onclick=()=>$('date-dialog').close();$('date-input').addEventListener('input',validateDateInput);$('date-form').onsubmit=e=>{e.preventDefault();if(validateDateInput()&&!loading)loadEdition($('date-input').value);};
for(const id of ['reader','about','clear-dialog','date-dialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();}});
$('font-up').onclick=()=>{state.fontSize=Math.min(26,state.fontSize+1);applyFont();persist();};$('font-down').onclick=()=>{state.fontSize=Math.max(16,state.fontSize-1);applyFont();persist();};$('theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';theme();render();persist();};
$('clear-data').onclick=()=>$('clear-dialog').showModal();$('clear-cancel').onclick=()=>$('clear-dialog').close();$('clear-confirm').onclick=()=>{try{storage.removeItem('xinliu:v1');storage.removeItem('xinliu:v2');}catch{}stored={editions:{}};Object.assign(state,{readIds:[],savedIds:[],fontSize:19,theme:'light'});theme();applyFont();render();$('clear-dialog').close();toast('已清除这个浏览器的阅读记录。');};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus();}});
window.addEventListener('popstate',()=>{const date=new URL(location.href).searchParams.get('date');loadEdition(editionEntry(catalog,date)?date:catalog.latest,{historyMode:null});});
async function init(){theme();applyFont();$('date-picker').disabled=true;$('load-error').hidden=true;try{catalog=await fetchJSON(new URL('./editions/index.json',import.meta.url));if(!catalog.editions?.length||!editionEntry(catalog,catalog.latest))throw new Error();catalog.editions.sort((a,b)=>b.date.localeCompare(a.date));const requested=new URL(location.href).searchParams.get('date');await loadEdition(editionEntry(catalog,requested)?requested:catalog.latest,{historyMode:'replace'});if(requested&&!editionEntry(catalog,requested))toast('这一天暂无简报，已打开最新一期。');}catch{$('load-error').hidden=false;$('result-count').textContent='暂时没有读到简报';}}
$('retry-load').onclick=init;init();
